"use client";

import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useProducts } from "@/features/products/useProducts";
import { useAuth } from "@/contexts/AuthContext";
import { authenticatedFetch } from "@/lib/auth/api-client";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { MessageSquare, Calendar, Package, ChevronLeft, ChevronRight } from "lucide-react";

interface ConversationListItem {
  id: string;
  started_at: string;
  message_count: number;
  product_id: string | null;
  product_name: string | null;
  last_message: string | null;
  last_message_at: string | null;
}

interface ConversationsResponse {
  conversations: ConversationListItem[];
  total: number;
  page: number;
  limit: number;
}

interface ConversationDetail {
  id: string;
  product_name: string | null;
  started_at: string;
  message_count: number;
  messages: Array<{
    id: string;
    role: "user" | "assistant";
    content: string;
    created_at: string;
  }>;
}

async function fetchConversations(
  shopId: string,
  productId: string | null,
  dateFrom: string | null,
  dateTo: string | null,
  page: number,
  limit: number
): Promise<ConversationsResponse> {
  const params = new URLSearchParams({
    page: page.toString(),
    limit: limit.toString(),
  });
  
  if (productId) {
    params.append("productId", productId);
  }
  if (dateFrom) {
    params.append("dateFrom", dateFrom);
  }
  if (dateTo) {
    params.append("dateTo", dateTo);
  }

  const response = await authenticatedFetch(
    `/api/analytics/conversations?${params.toString()}`
  );

  if (!response.ok) {
    throw new Error("Failed to fetch conversations");
  }

  return response.json();
}

async function fetchConversationDetail(
  conversationId: string
): Promise<ConversationDetail> {
  const response = await authenticatedFetch(
    `/api/analytics/conversations/${conversationId}`
  );

  if (!response.ok) {
    throw new Error("Failed to fetch conversation detail");
  }

  return response.json();
}

export default function ConversationsPage() {
  const { shopId } = useAuth();
  const { data: products = [] } = useProducts();
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null);
  const [dateFrom, setDateFrom] = useState<string>("");
  const [dateTo, setDateTo] = useState<string>("");
  const [page, setPage] = useState(1);
  const [selectedConversationId, setSelectedConversationId] = useState<string | null>(null);
  const limit = 20;

  const { data, isLoading, error } = useQuery({
    queryKey: ["conversations", shopId, selectedProductId, dateFrom, dateTo, page],
    queryFn: () =>
      fetchConversations(
        shopId,
        selectedProductId,
        dateFrom || null,
        dateTo || null,
        page,
        limit
      ),
    enabled: !!shopId,
  });

  const {
    data: conversationDetail,
    isLoading: isLoadingDetail,
  } = useQuery({
    queryKey: ["conversation", selectedConversationId],
    queryFn: () => fetchConversationDetail(selectedConversationId!),
    enabled: !!selectedConversationId,
  });

  const totalPages = data ? Math.ceil(data.total / limit) : 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">会話ログ</h1>
        <p className="text-sm text-gray-600 mt-1">
          AIエージェントとの会話履歴を確認できます
        </p>
      </div>

      {/* フィルタリングバー */}
      <div className="bg-white rounded-md border p-4 space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="space-y-2">
            <Label htmlFor="product">商品</Label>
            <Select
              value={selectedProductId || "all"}
              onValueChange={(value) =>
                setSelectedProductId(value === "all" ? null : value)
              }
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">すべての商品</SelectItem>
                {products.map((product) => (
                  <SelectItem key={product.id} value={product.id}>
                    {product.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="dateFrom">開始日</Label>
            <Input
              id="dateFrom"
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="dateTo">終了日</Label>
            <Input
              id="dateTo"
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* 会話一覧テーブル */}
      <div className="bg-white rounded-md border">
        {isLoading ? (
          <div className="p-8 text-center text-gray-500">読み込み中...</div>
        ) : error ? (
          <div className="p-8 text-center text-red-500">
            エラーが発生しました: {error instanceof Error ? error.message : "Unknown error"}
          </div>
        ) : !data || data.conversations.length === 0 ? (
          <div className="p-8 text-center text-gray-500">
            会話ログがありません
          </div>
        ) : (
          <>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>開始日時</TableHead>
                    <TableHead>商品名</TableHead>
                    <TableHead>メッセージ数</TableHead>
                    <TableHead>最新メッセージ</TableHead>
                    <TableHead className="text-right">操作</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.conversations.map((conv) => (
                    <TableRow key={conv.id}>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Calendar className="h-4 w-4 text-gray-400" />
                          <span className="text-sm">
                            {new Date(conv.started_at).toLocaleString("ja-JP")}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        {conv.product_name ? (
                          <div className="flex items-center gap-2">
                            <Package className="h-4 w-4 text-gray-400" />
                            <span className="text-sm">{conv.product_name}</span>
                          </div>
                        ) : (
                          <span className="text-sm text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <MessageSquare className="h-4 w-4 text-gray-400" />
                          <span className="text-sm">{conv.message_count}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        {conv.last_message ? (
                          <span className="text-sm text-gray-600 truncate max-w-xs block">
                            {conv.last_message}
                          </span>
                        ) : (
                          <span className="text-sm text-gray-400">-</span>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setSelectedConversationId(conv.id)}
                        >
                          詳細を見る
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>

            {/* ページネーション */}
            {totalPages > 1 && (
              <div className="p-4 border-t flex items-center justify-between">
                <div className="text-sm text-gray-600">
                  {data.total}件中 {(page - 1) * limit + 1}〜{Math.min(page * limit, data.total)}件を表示
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    disabled={page === 1}
                  >
                    <ChevronLeft className="h-4 w-4" />
                    前へ
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                    disabled={page === totalPages}
                  >
                    次へ
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* 会話詳細モーダル */}
      <Dialog
        open={!!selectedConversationId}
        onOpenChange={(open) => !open && setSelectedConversationId(null)}
      >
        <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>会話詳細</DialogTitle>
          </DialogHeader>
          {isLoadingDetail ? (
            <div className="p-8 text-center text-gray-500">読み込み中...</div>
          ) : conversationDetail ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <span className="font-semibold">商品名:</span>{" "}
                  {conversationDetail.product_name || "-"}
                </div>
                <div>
                  <span className="font-semibold">開始日時:</span>{" "}
                  {new Date(conversationDetail.started_at).toLocaleString("ja-JP")}
                </div>
                <div>
                  <span className="font-semibold">メッセージ数:</span>{" "}
                  {conversationDetail.message_count}
                </div>
              </div>

              <div className="border-t pt-4 space-y-4">
                <h3 className="font-semibold">メッセージ履歴</h3>
                <div className="space-y-3">
                  {conversationDetail.messages.map((msg) => (
                    <div
                      key={msg.id}
                      className={`p-3 rounded-lg ${
                        msg.role === "user"
                          ? "bg-blue-50 ml-8"
                          : "bg-gray-50 mr-8"
                      }`}
                    >
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-xs font-semibold">
                          {msg.role === "user" ? "ユーザー" : "AIアシスタント"}
                        </span>
                        <span className="text-xs text-gray-500">
                          {new Date(msg.created_at).toLocaleString("ja-JP")}
                        </span>
                      </div>
                      <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : null}
        </DialogContent>
      </Dialog>
    </div>
  );
}
